def count_ways(target, parts):
    """Ways to make target from parts, reusing parts, order ignored."""
    ways = [1] + [0] * target          # ways[t] = number of ways to make t
    for part in parts:
        for t in range(part, target + 1):
            ways[t] += ways[t - part]  # use this part once more on top of t - part
    return ways[target]


def best_path(triangle):
    """Largest top-to-bottom total moving to an adjacent number below, worked from the bottom up."""
    best = list(triangle[-1])          # best[i] = best total from this row's cell i down
    for row in reversed(triangle[:-1]):
        best = [value + max(best[i], best[i + 1]) for i, value in enumerate(row)]
    return best[0]


def solve():
    return count_ways(5, [1, 2, 5]), best_path([[1], [2, 3], [4, 5, 6]])


